for name,pairs in changes.items():
 p=r/name;s=p.read_text()
 for old,new in pairs:
  if s.count(old)!=1:raise SystemExit("Unexpected source for pending-paperwork save fix: "+name)
  s=s.replace(old,new,1)
 p.write_text(s)
(r/'test/pending-paperwork-save.test.mjs').write_text("import test from 'node:test';import assert from 'node:assert/strict';import {initialState,execute,engine,libertana} from '../server/engine.mjs';import {createApplication} from '../server/index.mjs';import {mkdtempSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import path from 'node:path';import {createHmac,randomUUID} from 'node:crypto';\nconst progress=extra=>({assessment:'pending',approval:'waiting',reason:'',moveStatus:'none',moveDate:'',due:'2026-12-01',note:'Pending paperwork; follow-up recorded.',...extra});\nfunction fixture(building='crenshaw'){return execute(initialState(false),'u0',{op:'createLead',createdId:'L_pending_save_test',args:[{first:'Synthetic',last:'Pending',building,rep:'u2',payer:'CalAIM Community Supports',cca:'Libertana'}]});}\ntest('LA referral saves notes, reminder and scheduled move-in while Libertana packet remains incomplete',()=>{\n for(const building of ['crenshaw','bellevue','plaza']){let state=fixture(building);const l=state.leads[0];l.files=[{id:'file_synthetic',name:'Original.pdf',type:'application/pdf'}];const packet=JSON.stringify(l.libertana),steps=structuredClone(l.countyWorkflow.steps);\n state=execute(state,'u2',{op:'saveReferral',expectedVersion:1,args:[l.id,{caller:{phone:'555-010-0199'},notes:'Original referral note'},progress({moveStatus:'scheduled',moveDate:'2026-12-02',note:'Called the case manager. Packet still pending.'})]});\n const tl=engine(state,'u0'),saved=tl.Lead(l.id);assert.equal(saved.moveIn,'2026-12-02');assert.equal(saved.caller.phone,'555-010-0199');assert.equal(saved.referralProgress.note,'Called the case manager. Packet still pending.');assert.equal(saved.referralProgress.due,'2026-12-01');assert.equal(saved.version,2);assert.equal(JSON.stringify(saved.libertana),packet);assert.equal(libertana.complete(saved),false);assert.equal(tl.referralSummary(saved).approval,'waiting');assert.equal(tl.countySummary(saved).ready,false);assert.equal(saved.files[0].id,'file_synthetic');for(const key of ['libertana_packet','libertana_submission','authorization'])if(steps[key])assert.deepEqual(saved.countyWorkflow.steps[key],steps[key]);\n state=execute(state,'u2',{op:'saveReferral',expectedVersion:2,args:[l.id,{cca:'Libertana'},progress({moveStatus:'scheduled',moveDate:'2026-12-03',note:'Still waiting; reminder updated.',due:'2026-12-04'})]});assert.equal(state.leads[0].moveIn,'2026-12-03');assert.equal(state.leads[0].referralProgress.note,'Still waiting; reminder updated.');\n }\n});\ntest('reported move-in never invents packet signatures, assessment acceptance or program approval',()=>{\n const state=fixture(),saved=execute(state,'u0',{op:'saveReferral',expectedVersion:1,args:[state.leads[0].id,{},progress({moveStatus:'moved',moveDate:'2026-11-16'})]}),l=saved.leads[0],tl=engine(saved,'u0');assert.equal(l.stage,'movein');assert.equal(tl.referralSummary(l).assessment,'pending');assert.equal(tl.referralSummary(l).approval,'waiting');assert.equal(libertana.complete(l),false);assert.equal(l.countyWorkflow.steps.libertana_packet.status,'not_started');assert.equal(tl.leadMatchesFilter(l,'libertana-unsigned'),true);\n});\ntest('HTTP save with unfinished packet commits once, remains retry-safe and preserves permission/version checks',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),'pending-packet-save-')),secret='synthetic-save-secret',app=await createApplication({schedule:false,env:{NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',DATABASE_URL:'',SQLITE_PATH:path.join(dir,'db'),APP_ORIGIN:'',SESSION_SECRET:secret}});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;\n try{for(const uid of ['u0','u2','u3'])await app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',secret).update(uid).digest('hex'),uid,Date.now()+60000,'csrf']);\n const post=(uid,command)=>fetch(origin+'/api/commands',{method:'POST',headers:{Origin:origin,Cookie:'tl_session='+uid,'X-CSRF-Token':'csrf','Content-Type':'application/json'},body:JSON.stringify(command)});\n const create={id:randomUUID(),op:'createLead',createdId:'L_http_pending',args:[{first:'Synthetic',last:'HTTP',building:'crenshaw',rep:'u2',payer:'CalAIM Community Supports',cca:'Libertana'}]};assert.equal((await post('u0',create)).status,200);\n const command={id:randomUUID(),op:'saveReferral',expectedVersion:1,args:['L_http_pending',{cca:'Libertana'},progress({moveStatus:'scheduled',moveDate:'2026-12-02'})]};assert.equal((await post('u3',command)).status,404);assert.equal((await post('u2',command)).status,200);assert.equal((await post('u2',command)).status,200);assert.equal((await post('u2',{...command,id:randomUUID()})).status,409);\n const response=await fetch(origin+'/api/state',{headers:{Cookie:'tl_session=u2'}}),boot=await response.json(),l=boot.state.leads.find(l=>l.id==='L_http_pending');assert.equal(l.version,2);assert.equal(l.moveIn,'2026-12-02');assert.equal(l.referralProgress.note,progress().note);assert.equal(libertana.complete(l),false);const events=await app.store.query('SELECT action FROM audit_log WHERE record_id=$1 AND action=$2',['L_http_pending','saveReferral']);assert.equal(events.length,1);\n }finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n});\n")
